// The register-cache model (common/translator/regeffect.h) against the runtime's ops: for random encodings of every op the translator emits
// (generated by opcheck_gen into regcheck.cpp), changing any state the model says the op does not read must not change any result, state the
// model says it does not write must come out unchanged, and state it says the op always writes must not depend on its old value.
#include "check.h"
#include "ppc_fixture.h"
#include "translator/regeffect.h"
#include <cstdio>
#include <cstring>
#include <random>
#include <vector>

struct RegCase { const char* name; uint32_t word; bool mem, idx; uint64_t use[2], may[2], must[2]; void (*fn)(ppc::Ctx&); };
extern const RegCase kRegCases[];
extern const size_t kRegCaseCount;

static uint32_t ppc_b(uint32_t w) { return (w >> 11) & 31; }
static uint32_t ppc_a(uint32_t w) { return (w >> 16) & 31; }

namespace {
using uc::res::COUNT;
constexpr uint32_t kWindow = 0x800FE000u, kWindowSize = 0x4000u;   // every access of a memory case falls in here
constexpr uint32_t kBase = 0x80100000u;

uint64_t get(const ppc::Ctx& c, int i) {
    namespace r = uc::res;
    uint64_t v = 0;
    if (i < r::F) return c.r[i];
    if (i < r::P) { std::memcpy(&v, &c.f[i - r::F], 8); return v; }
    if (i < r::CR) { std::memcpy(&v, &c.ps1[i - r::P], 8); return v; }
    if (i < r::CA) return c.cr[i - r::CR];
    if (i >= r::GQR && i < r::FPSCR) return c.gqr[i - r::GQR];
    switch (i) {
        case r::CA: return c.xer_ca; case r::OV: return c.xer_ov; case r::SO: return c.xer_so;
        case r::LR: return c.lr; case r::CTR: return c.ctr; case r::FPSCR: return c.fpscr; case r::RES: return c.reserve_addr; case r::POLL: return c.poll_count;
        default: return 0;
    }
}
void set(ppc::Ctx& c, int i, uint64_t v) {
    namespace r = uc::res;
    if (i < r::F) c.r[i] = uint32_t(v);
    else if (i < r::P) std::memcpy(&c.f[i - r::F], &v, 8);
    else if (i < r::CR) std::memcpy(&c.ps1[i - r::P], &v, 8);
    else if (i < r::CA) c.cr[i - r::CR] = uint8_t(v);
    else if (i >= r::GQR && i < r::FPSCR) c.gqr[i - r::GQR] = uint32_t(v);
    else switch (i) {
        case r::CA: c.xer_ca = uint8_t(v); break; case r::OV: c.xer_ov = uint8_t(v); break; case r::SO: c.xer_so = uint8_t(v); break;
        case r::LR: c.lr = uint32_t(v); break; case r::CTR: c.ctr = uint32_t(v); break; case r::FPSCR: c.fpscr = uint32_t(v); break;
        case r::RES: c.reserve_addr = uint32_t(v); break; case r::POLL: c.poll_count = uint32_t(v); break;
        default: break;
    }
}
bool in(const uint64_t (&s)[2], int i) { return (s[i >> 6] >> (i & 63)) & 1; }

std::mt19937_64 rng(7);
uint64_t fp_value() {
    double d;
    switch (rng() % 8) {
        case 0: d = 0.0; break;
        case 1: d = -0.0; break;
        case 2: { const float f = float(int64_t(rng() % 2000) - 1000) / 7.0f; d = f; break; }
        case 3: d = double(int64_t(rng() % 200000) - 100000) / 3.0; break;
        case 4: d = 1.0 / 0.0; break;
        case 5: { uint64_t b = rng(); return b; }
        case 6: d = std::ldexp(1.0, int(rng() % 300) - 150); break;
        default: d = double(int64_t(rng() % 7) - 3); break;
    }
    uint64_t b; std::memcpy(&b, &d, 8); return b;
}
uint64_t value(const RegCase& k, int i) {
    namespace r = uc::res;
    if (i < r::F) {
        if (!k.mem) return uint32_t(rng());
        return (k.idx && i == int(ppc_b(k.word))) ? uint32_t(rng() % 0x400) & ~7u : kBase + (uint32_t(rng() % 0x800) & ~7u);
    }
    if (i < r::CR) return fp_value();
    if (i < r::CA) return rng() & 0xF;
    if (i <= r::SO) return rng() & 1;
    return uint32_t(rng());
}
}  // namespace


struct Out { uint64_t v[COUNT]; std::vector<uint8_t> mem; };

int main() {
    Fix fx;
    std::vector<uint8_t> pattern(kWindowSize);
    size_t failures = 0, checks = 0;
    auto run = [&](const RegCase& k, const uint64_t* state) {
        ppc::Ctx& c = fx.c;
        std::memcpy(c.mem + kWindow, pattern.data(), kWindowSize);
        for (int i = 0; i < COUNT; ++i) set(c, i, state[i]);
        k.fn(c);
        Out o;
        for (int i = 0; i < COUNT; ++i) o.v[i] = get(c, i);
        o.mem.assign(c.mem + kWindow, c.mem + kWindow + kWindowSize);
        return o;
    };
    auto report = [&](const RegCase& k, const char* what, int i) {
        if (++failures <= 40) std::fprintf(stderr, "%s %08X: %s resource %d\n", k.name, k.word, what, i);
    };
    for (size_t n = 0; n < kRegCaseCount; ++n) {
        const RegCase& k = kRegCases[n];
        for (int trial = 0; trial < 3; ++trial) {
            for (auto& b : pattern) b = uint8_t(rng());
            uint64_t s[COUNT];
            for (int i = 0; i < COUNT; ++i) s[i] = value(k, i);
            if (std::strcmp(k.name, "stwcx_") == 0 && trial == 0) s[uc::res::RES] = (s[ppc_a(k.word)] + s[ppc_b(k.word)]) | 1u;
            const Out base = run(k, s);
            for (int i = 0; i < COUNT; ++i) {
                ++checks;
                if (!in(k.may, i) && base.v[i] != s[i]) report(k, "writes unmodelled", i);
            }
            for (int x = 0; x < COUNT; ++x) {
                if (in(k.use, x) || (in(k.may, x) && !in(k.must, x))) continue;
                uint64_t t[COUNT];
                std::memcpy(t, s, sizeof t);
                for (int tries = 0; tries < 8 && t[x] == s[x]; ++tries) t[x] = value(k, x);
                if (t[x] == s[x]) continue;
                const Out o = run(k, t);
                ++checks;
                for (int i = 0; i < COUNT; ++i) {
                    if (i == x) {
                        if (in(k.must, x) && o.v[i] != base.v[i]) report(k, "must-write depends on the old value of", x);
                        continue;
                    }
                    if (o.v[i] != base.v[i]) { report(k, "reads unmodelled", x); break; }
                }
                if (o.mem != base.mem) report(k, "memory depends on unmodelled", x);
            }
        }
    }
    std::printf("%zu cases, %zu checks, %zu failures\n", kRegCaseCount, checks, failures);
    CHECK(kRegCaseCount > 1000);
    CHECK(failures == 0);
    return 0;
}
